"use client";
import {useEffect,useState} from "react";
import AppNavigation from "../components/AppNavigation";
const API=process.env.NEXT_PUBLIC_API_URL||"http://127.0.0.1:8000";
type Doc={id:string;title:string;issuing_authority:string;document_type:string;education_level:string;curriculum_version:string;publication_year:string;source_url:string;original_filename:string;sha256:string;extraction_status:string;verification_status:string;created_at:string|null;extracted_characters:number;linked_entries:number;linked_topics:number;linked_questions:number};
type Outcome={id:string;outcome_text:string;competency:string;verification_status:string;page_reference:string};
type Entry={id:string;grade_code:string;subject_name:string;document_id:string;document_title:string;parent_title:string|null;entry_type:string;title:string;description:string;page_reference:string;source_excerpt:string;verification_status:string;created_at:string|null;learning_outcomes:Outcome[]};
type Summary={documents:number;documents_verified:number;entries:number;entries_verified:number;learning_outcomes:number;learning_outcomes_verified:number;note:string};
export default function CurriculumPage(){
 const [docs,setDocs]=useState<Doc[]>([]),[entries,setEntries]=useState<Entry[]>([]);
 const [summary,setSummary]=useState<Summary|null>(null),[selected,setSelected]=useState("");
 const [sourceFile,setSourceFile]=useState<File|null>(null),[csvFile,setCsvFile]=useState<File|null>(null);
 const [title,setTitle]=useState(""),[version,setVersion]=useState(""),[year,setYear]=useState(""),[level,setLevel]=useState(""),[url,setUrl]=useState("");
 const [busy,setBusy]=useState(false),[notice,setNotice]=useState(""),[error,setError]=useState("");
 const [importErrors,setImportErrors]=useState<{row:number;error:string}[]>([]);
 const [entriesHidden,setEntriesHidden]=useState(false),[selectedEntryIds,setSelectedEntryIds]=useState<string[]>([]);
 const [entrySearch,setEntrySearch]=useState(""),[gradeFilter,setGradeFilter]=useState(""),[subjectFilter,setSubjectFilter]=useState(""),[documentFilter,setDocumentFilter]=useState("recent"),[statusFilter,setStatusFilter]=useState("");
 async function load(){try{const [d,e,s]=await Promise.all([fetch(`${API}/api/v1/curriculum/documents`),fetch(`${API}/api/v1/curriculum/entries`),fetch(`${API}/api/v1/curriculum/summary`)]);if(!d.ok||!e.ok||!s.ok)throw Error("Could not load curriculum workspace");const docsData:Doc[]=await d.json();setDocs(docsData);setEntries(await e.json());setSummary(await s.json());if(!selected&&docsData.length)setSelected(docsData[0].id)}catch(ex){setError(ex instanceof Error?ex.message:"Backend unavailable")}}
 useEffect(()=>{load()},[]);
 const selectedDoc=docs.find(d=>d.id===selected);
 const isNcdc=(d:Doc)=>/ncdc|national curriculum development centre/i.test(d.issuing_authority||"");
 const recentVerifiedNcdcDocs=docs.filter(d=>d.verification_status==="verified"&&isNcdc(d)).sort((a,b)=>Date.parse(b.created_at||"")-Date.parse(a.created_at||"")).slice(0,2);
 const recentDocIds=new Set(recentVerifiedNcdcDocs.map(d=>d.id));
 const grades=Array.from(new Set(entries.map(e=>e.grade_code))).sort((a,b)=>a.localeCompare(b,undefined,{numeric:true}));
 const subjects=Array.from(new Set(entries.filter(e=>!gradeFilter||e.grade_code===gradeFilter).map(e=>e.subject_name))).sort();
 const filteredEntries=entries.filter(e=>{
  if(documentFilter==="recent"&&!recentDocIds.has(e.document_id)&&!(entrySearch.trim()||gradeFilter||subjectFilter||statusFilter))return false;
  if(documentFilter!=="recent"&&documentFilter!=="all"&&e.document_id!==documentFilter)return false;
  if(gradeFilter&&e.grade_code!==gradeFilter)return false;
  if(subjectFilter&&e.subject_name!==subjectFilter)return false;
  if(statusFilter&&e.verification_status!==statusFilter)return false;
  const q=entrySearch.trim().toLocaleLowerCase();
  if(q&&!([e.title,e.description,e.parent_title||"",e.page_reference,e.document_title,e.grade_code,e.subject_name,e.entry_type].join(" ").toLocaleLowerCase().includes(q)))return false;
  return true;
 });
 const visibleSelectedIds=filteredEntries.filter(e=>selectedEntryIds.includes(e.id)).map(e=>e.id);
 const formatDate=(value:string|null)=>value?new Date(value).toLocaleDateString():"Date unavailable";
 async function uploadDocument(){if(!sourceFile){setError("Choose a curriculum source file first.");return}setBusy(true);setError("");setNotice("");try{const f=new FormData();f.append("file",sourceFile);f.append("title",title);f.append("curriculum_version",version);f.append("publication_year",year);f.append("education_level",level);f.append("source_url",url);f.append("document_type","syllabus");const r=await fetch(`${API}/api/v1/curriculum/documents/upload`,{method:"POST",body:f});const d=await r.json();if(!r.ok)throw Error(d.detail||"Upload failed");setNotice(`Source uploaded. Text extraction: ${d.document.extraction_status}. Review the original NCDC document before marking it verified.`);setSourceFile(null);await load();setSelected(d.document.id)}catch(ex){setError(ex instanceof Error?ex.message:"Upload failed")}finally{setBusy(false)}}
 async function reviewDocument(decision:"verified"|"unverified"|"rejected"){if(!selected)return;setBusy(true);setError("");try{const r=await fetch(`${API}/api/v1/curriculum/documents/${selected}/review`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({decision,reviewer_name:"Curriculum Reviewer",notes:"Reviewed against the original source document."})});const d=await r.json();if(!r.ok)throw Error(d.detail||"Review failed");setNotice(`Source document status: ${d.verification_status}.`);await load()}catch(ex){setError(ex instanceof Error?ex.message:"Review failed")}finally{setBusy(false)}}
 async function retryExtraction(){if(!selected)return;setBusy(true);setError("");try{const r=await fetch(`${API}/api/v1/curriculum/documents/${selected}/re-extract`,{method:"POST"});const d=await r.json();if(!r.ok)throw Error(d.detail||"Text extraction retry failed");setNotice(`Extraction status: ${d.document.extraction_status}. ${d.document.extracted_characters.toLocaleString()} characters extracted.`);await load()}catch(ex){setError(ex instanceof Error?ex.message:"Text extraction retry failed")}finally{setBusy(false)}}
 async function deleteDocument(doc:Doc){
  if(doc.linked_entries>0||doc.linked_topics>0||doc.linked_questions>0){setError(`Cannot delete “${doc.title}”: it is still referenced by ${doc.linked_entries} curriculum entr${doc.linked_entries===1?"y":"ies"}, ${doc.linked_topics} topic record${doc.linked_topics===1?"":"s"}, and ${doc.linked_questions} generated question record${doc.linked_questions===1?"":"s"}. Remove or reassign those references first.`);return}
  if(!window.confirm(`Permanently delete the registered source document “${doc.title}” and its stored file? This action cannot be undone. No curriculum entries are linked to this document.`))return;
  setBusy(true);setError("");setNotice("");
  try{
   const r=await fetch(`${API}/api/v1/curriculum/documents/${doc.id}`,{method:"DELETE"});
   const d=await r.json();if(!r.ok)throw Error(d.detail||"Document deletion failed");
   if(selected===doc.id)setSelected("");
   setNotice(`Deleted source document “${doc.title}”.`);
   await load();
  }catch(ex){setError(ex instanceof Error?ex.message:"Document deletion failed")}
  finally{setBusy(false)}
 }
 async function deleteSelectedEntries(){const ids=visibleSelectedIds;if(!ids.length)return;if(!window.confirm(`Permanently delete ${ids.length} selected curriculum entries currently shown by these filters? Child entries and associated learning outcomes will also be deleted.`))return;setBusy(true);setError("");try{const r=await fetch(`${API}/api/v1/curriculum/entries/delete-bulk`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({ids})});const d=await r.json();if(!r.ok)throw Error(d.detail||"Delete failed");setNotice(`Deleted ${d.deleted_entries} curriculum entries. Related topic records used by questions were retained but returned to unverified status.`);setSelectedEntryIds([]);await load()}catch(ex){setError(ex instanceof Error?ex.message:"Delete failed")}finally{setBusy(false)}}
 async function importCsv(){if(!selected||!csvFile){setError("Select a verified source document and a CSV file.");return}setBusy(true);setError("");setImportErrors([]);try{const f=new FormData();f.append("file",csvFile);const r=await fetch(`${API}/api/v1/curriculum/documents/${selected}/import-csv`,{method:"POST",body:f});const d=await r.json();if(!r.ok)throw Error(d.detail||"Import failed");setImportErrors(Array.isArray(d.errors)?d.errors:[]);setNotice(`Imported ${d.nodes_created} curriculum entries and ${d.learning_outcomes_created} learning outcomes. ${d.rows_with_errors} row errors. ${d.nodes_created===0&&d.rows_with_errors>0?"No entries were imported; inspect the row errors below.":""}`);setCsvFile(null);await load()}catch(ex){setError(ex instanceof Error?ex.message:"Import failed")}finally{setBusy(false)}}
 async function reviewEntry(id:string,decision:"verified"|"rejected"){setBusy(true);setError("");try{const r=await fetch(`${API}/api/v1/curriculum/entries/${id}/review`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({decision,reviewer_name:"Curriculum Reviewer",notes:"Checked against source document and page reference."})});const d=await r.json();if(!r.ok)throw Error(d.detail||"Review failed");setNotice(`Entry '${d.title}' marked ${d.verification_status}. Verified topics become available to the question generator.`);await load()}catch(ex){setError(ex instanceof Error?ex.message:"Review failed")}finally{setBusy(false)}}
 async function reviewOutcome(id:string,decision:"verified"|"rejected"){setBusy(true);setError("");try{const r=await fetch(`${API}/api/v1/curriculum/outcomes/${id}/review`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({decision,reviewer_name:"Curriculum Reviewer",notes:"Checked against source wording and page reference."})});const d=await r.json();if(!r.ok)throw Error(d.detail||"Review failed");setNotice(`Learning outcome marked ${d.verification_status}.`);await load()}catch(ex){setError(ex instanceof Error?ex.message:"Review failed")}finally{setBusy(false)}}
 return <>
 <AppNavigation />
 <main className="wrap">
 <section className="hero"><h1>Ugandan Curriculum Content Manager</h1><p>Register official curriculum sources, extract readable text, import structured curriculum entries and review each item before it becomes available to question generation.</p><b>Source → Import → Verify → Use</b></section>
 {error&&<div className="alert error">{error}</div>}{notice&&<div className="alert">{notice}</div>}
 <section className="panel"><h2>Curriculum coverage register</h2><div className="statrow">{[[summary?.documents??0,"Documents"],[summary?.documents_verified??0,"Verified sources"],[summary?.entries??0,"Entries"],[summary?.entries_verified??0,"Verified entries"],[summary?.learning_outcomes??0,"Outcomes"],[summary?.learning_outcomes_verified??0,"Verified outcomes"]].map(([n,l])=><div className="stat" key={String(l)}><b>{n}</b><span>{l}</span></div>)}</div><p className="muted">These are database record counts, not a percentage or claim of complete NCDC coverage.</p></section>
 <section className="panel"><h2>1. Register an NCDC source document</h2><p className="muted">Upload a source you are authorised to use. PDF, DOCX, TXT and Markdown are supported; maximum 25 MB. Scanned PDFs may need OCR before text extraction works.</p>
 <label>Source file</label><input type="file" accept=".pdf,.docx,.txt,.md" onChange={e=>setSourceFile(e.target.files?.[0]||null)}/>
 <div className="grid two"><div><label>Document title</label><input value={title} onChange={e=>setTitle(e.target.value)} placeholder="e.g. Lower Secondary Mathematics Syllabus"/></div><div><label>Curriculum version / edition</label><input value={version} onChange={e=>setVersion(e.target.value)} placeholder="Edition or version as printed"/></div><div><label>Publication year</label><input value={year} onChange={e=>setYear(e.target.value)} placeholder="e.g. 2025"/></div><div><label>Education level</label><input value={level} onChange={e=>setLevel(e.target.value)} placeholder="e.g. Lower Secondary S1–S4"/></div></div>
 <label>Official source URL (optional)</label><input value={url} onChange={e=>setUrl(e.target.value)} placeholder="https://..."/><button className="primary" disabled={busy||!sourceFile} onClick={uploadDocument}>{busy?"Working...":"Upload and extract text"}</button></section>
 <section className="panel">
  <h2>Registered curriculum documents</h2>
  <p className="muted">Remove unnecessary source files here. For safety, SASA allows deletion only when a document has no curriculum entries, topic records or generated questions referencing it. Existing curriculum entries, learning outcomes, topics and questions are never automatically deleted by this action.</p>
  {docs.length===0?<p className="muted">No source documents have been registered yet.</p>:<div className="document-management-list">
   {docs.map(d=><div key={d.id} className="document-management-row">
    <div className="document-management-info"><b>{d.title}</b><span>{d.original_filename} · {d.verification_status} · {d.linked_entries} linked entr{d.linked_entries===1?"y":"ies"} · {d.linked_topics} topic record{d.linked_topics===1?"":"s"} · {d.linked_questions} question record{d.linked_questions===1?"":"s"}</span></div>
    <button className="danger document-delete-button" disabled={busy||d.linked_entries>0||d.linked_topics>0||d.linked_questions>0} title={d.linked_entries>0||d.linked_topics>0||d.linked_questions>0?"Remove linked curriculum references first":"Delete this unused source document"} onClick={()=>deleteDocument(d)}>Delete</button>
   </div>)}
  </div>}
 </section>
 <section className="panel"><h2>2. Verify the source and import curriculum rows</h2><label>Registered source document</label><select value={selected} onChange={e=>setSelected(e.target.value)}><option value="">Select source document</option>{docs.map(d=><option key={d.id} value={d.id}>{d.title} · {d.verification_status}</option>)}</select>
 {selectedDoc&&<><p><b>{selectedDoc.title}</b></p><p className="muted">{selectedDoc.original_filename} · {selectedDoc.curriculum_version||"Version not recorded"} · {selectedDoc.extraction_status} · {selectedDoc.extracted_characters.toLocaleString()} extracted characters</p><p className="muted">SHA-256: {selectedDoc.sha256||"—"}</p>{selectedDoc.extraction_status!=="extracted"&&<div className="actions"><button className="secondary" disabled={busy} onClick={retryExtraction}>Retry text extraction</button><span className="muted">This retries the already registered file; it does not upload a duplicate.</span></div>}<div className="actions"><button className="secondary" disabled={busy} onClick={()=>reviewDocument("verified")}>Mark source verified</button><button className="danger" disabled={busy} onClick={()=>reviewDocument("rejected")}>Reject source</button><button className="secondary" disabled={busy} onClick={()=>reviewDocument("unverified")}>Return to unverified</button></div><p className="muted">Only mark verified after checking the issuing authority, edition, applicable classes and source document itself. This action unlocks CSV import; it does not mean SASA independently certified the document.</p>
 <div className="actions"><a href={`${API}/api/v1/curriculum/csv-template`} target="_blank" rel="noreferrer">Download CSV import template</a><a href={`${API}/api/v1/curriculum/documents/${selected}/text`} target="_blank" rel="noreferrer">View extracted text</a></div>
 <label>Upload completed curriculum CSV</label><input type="file" accept=".csv,text/csv" onChange={e=>setCsvFile(e.target.files?.[0]||null)}/><button className="primary" disabled={busy||selectedDoc.verification_status!=="verified"||!csvFile} onClick={importCsv}>Import curriculum CSV</button>{selectedDoc.verification_status!=="verified"&&<p className="muted">Verify the source document before importing rows.</p>}{importErrors.length>0&&<div className="alert warning" style={{marginTop:12}}><b>CSV rows that were not imported ({importErrors.length})</b><p className="muted">Check the class code, subject catalogue name and parent_title. For English, both “English” and “English Language” are now accepted and saved under the canonical English Language catalogue entry.</p><ul>{importErrors.slice(0,30).map((item,i)=><li key={`${item.row}-${i}`}>Row {item.row}: {item.error}</li>)}</ul>{importErrors.length>30&&<small>Showing first 30 errors.</small>}</div>}</>}
 </section>
 <section className="panel"><div className="actions" style={{justifyContent:"space-between",alignItems:"center",flexWrap:"wrap"}}><h2>3. Review imported curriculum entries</h2><div className="actions"><button className="secondary" onClick={()=>setEntriesHidden(v=>!v)}>{entriesHidden?"Show entries":"Hide entries"}</button><button className="secondary" onClick={()=>setSelectedEntryIds(filteredEntries.map(e=>e.id))} disabled={filteredEntries.length===0}>Select All</button><button className="secondary" onClick={()=>setSelectedEntryIds([])}>Clear Selection</button><button className="danger" disabled={busy||visibleSelectedIds.length===0} onClick={deleteSelectedEntries}>Delete Selected ({visibleSelectedIds.length})</button></div></div>
 <p className="muted">Newest imported entries appear first. By default, this view shows entries linked to the two most recently registered and verified NCDC documents. Searching by text, class, subject or review status automatically searches the full imported collection; you can also choose a specific document or all documents. Selection and bulk deletion apply to the entries currently displayed.</p>
 <div style={{background:"#f5f8fb",border:"1px solid #dbe4ee",borderRadius:10,padding:14,marginBottom:16}}><b>Most recently registered and verified NCDC documents</b>
 {recentVerifiedNcdcDocs.length===0?<p className="muted">No verified NCDC documents are registered yet. Verify an NCDC source document to have it appear here.</p>:<div className="grid two" style={{marginTop:10}}>{recentVerifiedNcdcDocs.map(d=><div key={d.id} style={{background:"white",border:"1px solid #dbe4ee",borderRadius:8,padding:12}}><b>{d.title}</b><p className="muted">{d.education_level||"Education level not specified"} · {d.publication_year||d.curriculum_version||"Edition not specified"}</p><small>Verified · Registered {formatDate(d.created_at)}</small></div>)}</div>}
 </div>
 {!entriesHidden&&<><div className="grid two" style={{marginBottom:12}}><div><label htmlFor="entry-search">Search imported entries</label><input id="entry-search" value={entrySearch} onChange={e=>setEntrySearch(e.target.value)} placeholder="Search title, topic, page, source, class or subject..."/></div><div><label>Source document</label><select value={documentFilter} onChange={e=>setDocumentFilter(e.target.value)}><option value="recent">Latest 2 verified NCDC documents</option><option value="all">All registered documents</option>{docs.map(d=><option key={d.id} value={d.id}>{d.title} · {d.verification_status}</option>)}</select></div><div><label>Class</label><select value={gradeFilter} onChange={e=>{setGradeFilter(e.target.value);setSubjectFilter("")}}><option value="">All classes</option>{grades.map(g=><option key={g} value={g}>{g}</option>)}</select></div><div><label>Subject</label><select value={subjectFilter} onChange={e=>setSubjectFilter(e.target.value)}><option value="">All subjects</option>{subjects.map(x=><option key={x} value={x}>{x}</option>)}</select></div><div><label>Review status</label><select value={statusFilter} onChange={e=>setStatusFilter(e.target.value)}><option value="">All statuses</option><option value="draft">Draft</option><option value="verified">Verified</option><option value="rejected">Rejected</option></select></div><div style={{display:"flex",alignItems:"end",gap:8}}><button className="secondary" onClick={()=>{setEntrySearch("");setGradeFilter("");setSubjectFilter("");setDocumentFilter("recent");setStatusFilter("");setSelectedEntryIds([])}}>Reset filters</button><span className="muted">Showing {filteredEntries.length} of {entries.length} entries</span></div></div>
 {filteredEntries.length===0?<p className="muted">No entries match the current filters. Choose “All registered documents”, change the class or subject, or adjust your search.</p>:filteredEntries.map(e=><article className="question" key={e.id}><label style={{display:"flex",gap:8,alignItems:"center"}}><input type="checkbox" checked={selectedEntryIds.includes(e.id)} onChange={ev=>setSelectedEntryIds(old=>ev.target.checked?[...old,e.id]:old.filter(id=>id!==e.id))}/>Select entry</label><small>{e.grade_code} · {e.subject_name} · {e.entry_type} · {e.verification_status} · Page {e.page_reference||"not specified"} · Imported {formatDate(e.created_at)}</small><p><b>{e.title}</b>{e.parent_title?` · under ${e.parent_title}`:""}</p>{e.description&&<p className="muted">{e.description}</p>}{e.source_excerpt&&<blockquote>{e.source_excerpt}</blockquote>}<small>Source: {e.document_title}</small><div className="actions">{e.verification_status!=="verified"&&<button className="secondary" disabled={busy} onClick={()=>reviewEntry(e.id,"verified")}>Verify entry</button>}{e.verification_status!=="rejected"&&<button className="danger" disabled={busy} onClick={()=>reviewEntry(e.id,"rejected")}>Reject entry</button>}</div>
 {e.learning_outcomes.map(o=><div key={o.id} style={{background:"#f5f8fb",padding:12,borderRadius:8,marginTop:10}}><small>Learning outcome · {o.verification_status} · Page {o.page_reference||"not specified"}</small><p>{o.outcome_text}</p>{o.competency&&<p className="muted">Competency: {o.competency}</p>}<div className="actions">{o.verification_status!=="verified"&&<button className="secondary" disabled={busy||e.verification_status!=="verified"} onClick={()=>reviewOutcome(o.id,"verified")}>Verify outcome</button>}{o.verification_status!=="rejected"&&<button className="danger" disabled={busy} onClick={()=>reviewOutcome(o.id,"rejected")}>Reject outcome</button>}</div></div>)}</article>)}
 </>}
 </section><p className="muted">SASA EduAssess Uganda · v0.1.0 · Imported content is not official until reviewed. Confirm permissions and current NCDC editions before commercial reuse.</p></main></>;
}
